{
  "mechanisms": [
    {
      "name": "outcome_gated_wm_reliance",
      "title": "Outcome-Gated WM Reliance",
      "description": "A latent gate tracks recent reward history with asymmetric win/loss sensitivities and modulates the baseline WM weight via a logistic transform.",
      "params": [
        {
          "name": "win_boost",
          "bounds": [0, 10]
        },
        {
          "name": "loss_suppression",
          "bounds": [0, 10]
        },
        {
          "name": "kappa",
          "bounds": [0, 1]
        }
      ],
      "evidence": "g = 0.0\n...\ntarget_g = (win_boost if r > 0.5 else -loss_suppression)\n            g = (1.0 - kappa) * g + kappa * target_g\n\n            eps = 1e-12\n            logit = lambda x: np.log(np.clip(x, eps, 1-eps)) - np.log(np.clip(1-x, eps, 1-eps))\n            inv_logit = lambda z: 1.0 / (1.0 + np.exp(-z))\n            wm_eff = inv_logit(logit(wm_weight) + g)",
      "expressible_in_slots": true
    },
    {
      "name": "unified_wm_update_decay",
      "title": "Unified WM Update and Decay",
      "description": "Working memory for the current state updates toward a one-hot action vector on reward, or decays toward uniform on no-reward, using a single shared rate parameter.",
      "params": [
        {
          "name": "kappa",
          "bounds": [0, 1]
        }
      ],
      "evidence": "one_hot = np.zeros(nA)\n            one_hot[a] = 1.0\n            if r > 0.5:\n                w[s, :] = (1.0 - kappa) * w[s, :] + kappa * one_hot\n            else:\n                w[s, :] = (1.0 - kappa) * w[s, :] + kappa * w_0[s, :]",
      "expressible_in_slots": true
    }
  ]
}
